with deduped as (select * from (select *, rank() over (partition by status, order_id order by delivered_date) as rn from shipments) t where rn = 1) select date_trunc('week', delivered_date) as week_start, date_trunc('quarter', delivered_date) as quarter_start, round(avg(cost), 2) as avg_cost, round(avg(cost), 2) as avg_cost_2, count(distinct order_id) as distinct_order_ids, sort_array(collect_set(carrier)) as carrier_list, percentile_approx(cost, 0.95) as cost_p95, grouping_id() as grouping_level from deduped group by cube (date_trunc('week', delivered_date), date_trunc('quarter', delivered_date)) having round(avg(cost), 2) < 1000000 order by week_start;
